//! The texts of the terminal interface in every language. A text is looked up by its
//! English wording (`tx(lang, "Wrong PIN")`), so the terminal code reads as it did; a
//! text with values has numbered places (`"Closed {0}"`) that `fill` puts them in, so a
//! translation may order them as its language needs. The table holds one row per text:
//! the English and the other 15 languages in `Language::ALL` order after English.
//! `every_terminal_text_is_translated` checks that every `tx` of `src/tui` has a row.

use crate::i18n::Language;
use std::collections::HashMap;
use std::sync::OnceLock;

/// The text `en` in `lang`; `en` itself when it has no row (the test catches that).
pub fn tx(lang: Language, en: &'static str) -> &'static str {
    if lang == Language::En {
        return en;
    }
    let Some(at) = Language::ALL.iter().position(|l| *l == lang) else {
        return en;
    };
    table()
        .get(en)
        .map(|row| row[at - 1])
        .filter(|t| !t.is_empty())
        .unwrap_or(en)
}

/// Marks a text kept in a table or a constant and translated where it is drawn
/// (`tx(lang, text)`), so `every_terminal_text_is_translated` finds it.
pub const fn en(text: &'static str) -> &'static str {
    text
}

/// `template` with `{0}`, `{1}`... replaced by `values`.
pub fn fill(template: &str, values: &[&dyn std::fmt::Display]) -> String {
    let mut out = template.to_string();
    for (i, v) in values.iter().enumerate() {
        out = out.replace(&format!("{{{i}}}"), &v.to_string());
    }
    out
}

/// `tx` then `fill`.
pub fn txf(lang: Language, en: &'static str, values: &[&dyn std::fmt::Display]) -> String {
    fill(tx(lang, en), values)
}

fn table() -> &'static HashMap<&'static str, [&'static str; 15]> {
    static TABLE: OnceLock<HashMap<&'static str, [&'static str; 15]>> = OnceLock::new();
    TABLE.get_or_init(|| TEXTS.iter().map(|(en, row)| (*en, *row)).collect())
}

